def family_init(ctx):
    """Dunnigan's bar grammar as an explicit state machine.

    Two independent setups run at once - one anchored on the N-bar low looking
    for a long, one on the N-bar high looking for a short. Each must pass the
    TEST (or a closing price reversal) before it will accept a THRUST, and each
    expires if the grammar is not completed in time.
    """
    import indicators as I
    bars = ctx.bars
    n = len(bars)
    hi = [float(b["h"]) for b in bars]
    lo = [float(b["l"]) for b in bars]
    cl = [float(b["c"]) for b in bars]
    atr = I.compute("atr", bars, period=int(ctx.p.atr_n))["atr"]

    N = int(ctx.p.swing_n)
    tol = float(ctx.p.test_tol)
    dep = float(ctx.p.depart)
    tw = int(ctx.p.test_win)
    thw = int(ctx.p.thrust_win)

    sig = [0] * n
    stp = [None] * n            # the initial stop that goes with each entry
    L = None                    # long setup
    S = None                    # short setup

    for t in range(n):
        a = atr[t]
        if t < 1 or a is None or a <= 0:
            continue
        up = hi[t] > hi[t - 1] and cl[t] > cl[t - 1]
        dn = lo[t] < lo[t - 1] and cl[t] < cl[t - 1]
        mid = (hi[t] + lo[t]) / 2.0

        keep_low_anchor = False
        keep_high_anchor = False

        # ---------------- the long side ----------------
        if L is not None:
            if L["stage"] == 0:
                if t > L["dl"]:
                    L = None
                else:
                    if lo[t] > L["l0"] + dep * L["a"]:
                        L["gone"] = True
                    test = (L["gone"] and lo[t] >= L["l0"]
                            and lo[t] <= L["l0"] + tol * L["a"])
                    cpr = (lo[t] < L["l0"] and cl[t] > cl[t - 1] and cl[t] > mid)
                    if test or cpr:
                        keep_low_anchor = cpr
                        L = {"stage": 1, "l0": L["l0"], "a": L["a"],
                             "dl": t + thw, "gone": L["gone"],
                             "stop": min(L["l0"], lo[t])}
            elif L["stage"] == 1:
                if t > L["dl"]:
                    L = None
                elif up:
                    sig[t] = 1
                    stp[t] = L["stop"]
                    L = None

        # ---------------- the short side ----------------
        if S is not None:
            if S["stage"] == 0:
                if t > S["dl"]:
                    S = None
                else:
                    if hi[t] < S["h0"] - dep * S["a"]:
                        S["gone"] = True
                    test = (S["gone"] and hi[t] <= S["h0"]
                            and hi[t] >= S["h0"] - tol * S["a"])
                    cpr = (hi[t] > S["h0"] and cl[t] < cl[t - 1] and cl[t] < mid)
                    if test or cpr:
                        keep_high_anchor = cpr
                        S = {"stage": 1, "h0": S["h0"], "a": S["a"],
                             "dl": t + thw, "gone": S["gone"],
                             "stop": max(S["h0"], hi[t])}
            elif S["stage"] == 1:
                if t > S["dl"]:
                    S = None
                elif dn:
                    sig[t] = -1
                    stp[t] = S["stop"]
                    S = None

        # ---------------- fresh anchors ----------------
        if t >= N - 1:
            if lo[t] <= min(lo[t - N + 1:t + 1]) and not keep_low_anchor:
                L = {"stage": 0, "l0": lo[t], "a": a, "dl": t + tw,
                     "gone": False, "stop": lo[t]}
            if hi[t] >= max(hi[t - N + 1:t + 1]) and not keep_high_anchor:
                S = {"stage": 0, "h0": hi[t], "a": a, "dl": t + tw,
                     "gone": False, "stop": hi[t]}

    ctx.sig = ctx.series(sig, "dunnigan")
    ctx.stp = ctx.series(stp, "dunnigan_stop")
    ctx._d = 0
    ctx._stop = None
    ctx._best = None            # highest close since entry (lowest for shorts)
    ctx._best_lo = None         # that bar's low (its high, for shorts)


def signal(ctx, i):
    s = ctx.sig[i]
    if s and not ctx.positions:
        ctx._d = s
        ctx._stop = ctx.stp[i]
        ctx._best = ctx.c[i]
        ctx._best_lo = ctx.l[i] if s > 0 else ctx.h[i]
    return int(s)


def exit_signal(ctx, i):
    """The counter-thrust trail: a thrust against the trade that also closes
    beyond the extreme bar of the move so far. Plus the initial stop."""
    if not ctx._d:
        return False
    c, h, l = ctx.c[i], ctx.h[i], ctx.l[i]
    pc, ph, pl = ctx.c[i - 1], ctx.h[i - 1], ctx.l[i - 1]
    if None in (pc, ph, pl):
        return False
    if ctx._d > 0:
        if ctx._stop is not None and c < ctx._stop - float(ctx.p.stop_pad):
            return True
        if ctx._best is None or c > ctx._best:
            ctx._best = c
            ctx._best_lo = l
        return (l < pl and c < pc) and ctx._best_lo is not None and c < ctx._best_lo
    if ctx._stop is not None and c > ctx._stop + float(ctx.p.stop_pad):
        return True
    if ctx._best is None or c < ctx._best:
        ctx._best = c
        ctx._best_lo = h
    return (h > ph and c > pc) and ctx._best_lo is not None and c > ctx._best_lo
